      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(dueDateAscResult);
  // 5. Test dueDate descending sort
  const dueDateDescResult = await api.functional.todoApp.member.todos.index(
    authenticatedConnection,
