    history[1].createdAt,
  );
  const time0 = new Date(history[0].createdAt);
  const time1 = new Date(history[1].createdAt);
  TestValidator.predicate("first entry is more recent", time0 > time1);
  // 8. Validate history entry structure
  for (const entry of history) {
    typia.assert(entry);
    TestValidator.equals("todoAppTodosId", entry.todoAppTodosId, todo.id);
    TestValidator.equals("todoAppMemberId", entry.todoAppMemberId, member.id);
    TestValidator.predicate(
      "has valid createdAt",
      entry.createdAt !== undefined,
    );
  }
}

