export async function postTodoAppAuthGuestJoin(props: {
  body: ITodoAppGuest.IJoin;
}): Promise<ITodoAppGuest.IAuthorized> {
  // 1. Check duplicate email (case-insensitive)
  const existingGuest = await MyGlobal.prisma.todo_app_guests.findFirst({
    where: {
      email: { equals: props.body.email.toLowerCase() },
    },
  });
  if (existingGuest) {
    throw new HttpException("Email already registered", 409);
  }
  // 2. Calculate timestamps
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 15 * 60 * 1000); // 15 minutes
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days
  // 3. Create guest account with hashed password
  const guest = await MyGlobal.prisma.todo_app_guests.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      email: props.body.email.toLowerCase(),
      password_hash: await PasswordUtil.hash(props.body.password),
      created_at: toISOStringSafe(now),
      updated_at: toISOStringSafe(now),
      deleted_at: null,
    },
    select: {
      id: true,
      email: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  // 4. Create user profile with display name (references guest as member_id)
  const profile = await MyGlobal.prisma.todo_app_user_profiles.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_member_id: guest.id,
      display_name: props.body.displayName,
      last_display_name_change_at: toISOStringSafe(now),
      created_at: toISOStringSafe(now),
      updated_at: toISOStringSafe(now),
    },
    select: {
      id: true,
      display_name: true,
      last_display_name_change_at: true,
    },
  });
  // 5. Create session record
  const session = await MyGlobal.prisma.todo_app_guest_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_guest_id: guest.id,
      ip: props.body.ip ?? "127.0.0.1",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpires),
    },
    select: {
      id: true,
    },
  });
  // 6. Generate JWT tokens
  const tokenPayload: {
    type: "guest";
    id: string;
    session_id: string;
    created_at: string;
  } = {
    type: "guest",
    id: guest.id,
    session_id: session.id,
    created_at: toISOStringSafe(now),
  };
  const access = jwt.sign(tokenPayload, MyGlobal.env.JWT_SECRET_KEY, {
    expiresIn: "15m",
    issuer: "autobe",
  });
  const refresh = jwt.sign(
    { ...tokenPayload, tokenType: "refresh" as const },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  // 7. Return IAuthorized
  return {
    id: guest.id,
    email: guest.email,
    token: {
      access,
      refresh,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    } satisfies IAuthorizationToken,
  } satisfies ITodoAppGuest.IAuthorized;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postTodoAppAuthGuestRefresh(props: {
  body: ITodoAppGuest.IRefresh;
}): Promise<ITodoAppGuest.IAuthorized> {
  let decoded: {
    type: "guest";
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    created_at: string;
  };
  try {
    decoded = jwt.verify(props.body.refresh, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as typeof decoded;
  } catch (err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "guest") {
    throw new HttpException("Invalid token type", 401);
  }
  const session = await MyGlobal.prisma.todo_app_guest_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_app_guest_id: decoded.id,
    },
  });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  const guest = await MyGlobal.prisma.todo_app_guests.findUniqueOrThrow({
    where: { id: decoded.id },
  });
  if (guest.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }
  const nowDate = new Date();
  const accessExpiresDate = new Date(nowDate.getTime() + 60 * 60 * 1000);
  const refreshExpiresDate = new Date(
    nowDate.getTime() + 7 * 24 * 60 * 60 * 1000,
  );
  const accessExpires: string & tags.Format<"date-time"> =
    accessExpiresDate.toISOString();
  const refreshExpires: string & tags.Format<"date-time"> =
    refreshExpiresDate.toISOString();
  const accessToken = jwt.sign(
    {
      type: "guest",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: nowDate.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refreshToken = jwt.sign(
    {
      type: "guest",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: nowDate.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  await MyGlobal.prisma.todo_app_guest_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpiresDate },
  });
  await MyGlobal.prisma.todo_app_guests.update({
    where: { id: decoded.id },
    data: { updated_at: nowDate },
  });
  return {
    id: decoded.id,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
    email: guest.email,
  };
}

